// ===== EDIT YOUR SETTINGS HERE =====
const settings = {
  // HubSpot API base URL. Keep as is.
  hubspotBaseUrl: 'https://api.hubapi.com',
  // Optional shared secret. If set, your form must send it in the header x-form-secret.
  sharedSecret: '',
};
const item = $input.first().json;
return [{ json: { settings, headers: item.headers || {}, body: item.body || {} } }];

const { settings, headers, body } = $input.first().json;
let b = body || {};
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
const pick = (...keys) => { for (const k of keys) { const v = b[k]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); } return ''; };
const errors = [];
if (settings.sharedSecret && (headers['x-form-secret'] || '') !== settings.sharedSecret) errors.push('bad or missing x-form-secret header');
const email = pick('email', 'Email', 'email_address', 'your-email').toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.push('a valid email is required');
let firstname = pick('firstname', 'first_name', 'firstName');
let lastname = pick('lastname', 'last_name', 'lastName');
const fullName = pick('name', 'full_name', 'fullName', 'your-name');
if (!firstname && fullName) { const parts = fullName.split(/\s+/); firstname = parts.shift(); lastname = lastname || parts.join(' '); }
const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
const countryMap = { 'UNITED STATES': 'US', 'USA': 'US', 'UNITED KINGDOM': 'GB', 'UK': 'GB', 'CANADA': 'CA', 'GERMANY': 'DE', 'FRANCE': 'FR', 'SPAIN': 'ES', 'ITALY': 'IT', 'NETHERLANDS': 'NL', 'IRELAND': 'IE', 'AUSTRALIA': 'AU' };
let country = pick('country', 'country_code').toUpperCase();
country = countryMap[country] || country;
const lead = {
  email,
  firstname: cap(firstname),
  lastname: cap(lastname),
  company: pick('company', 'company_name', 'organization'),
  phone: pick('phone', 'phone_number', 'tel').replace(/[^\d+]/g, ''),
  website: pick('website', 'url', 'site'),
  country,
  message: pick('message', 'comments', 'details', 'your-message'),
  budget: pick('budget'),
  timeline: pick('timeline', 'timeframe'),
  source: pick('utm_source', 'source'),
};
return [{ json: { valid: errors.length === 0, errors, lead } }];

const v = $('Validate and Normalize').first().json;
const found = $input.first().json;
const existing = (found.results || [])[0] || null;
const p = {};
for (const k of ['email', 'firstname', 'lastname', 'company', 'phone', 'website', 'country', 'message']) if (v.lead[k]) p[k] = v.lead[k];
if (!existing) { p.lifecyclestage = 'lead'; p.hs_lead_status = 'NEW'; }
return [{ json: { exists: !!existing, contactId: existing ? existing.id : null, properties: p } }];

const v = $('Validate and Normalize').first().json;
const b = $('Build Contact Payload').first().json;
const r = $input.first().json;
return [{ json: { ok: true, action: b.exists ? 'updated' : 'created', contactId: r.id, email: v.lead.email, name: ((v.lead.firstname || '') + ' ' + (v.lead.lastname || '')).trim(), company: v.lead.company || null } }];
